class Solution {
    public int subtractProductAndSum(int n) {
        int product = 1;
        int sum = 0;
        while (n > 0) {
            int digit = n % 10;
            product *= digit;
            sum += digit;
            n /= 10;
        }
        return product - sum;
    }
}

class Solution {
    public int subtractProductAndSum(int n) {
        String digits = Integer.toString(n);
        int product = 1;
        int sum = 0;
        for (int i = 0; i < digits.length(); i++) {
            int digit = digits.charAt(i) - '0';
            product *= digit;
            sum += digit;
        }
        return product - sum;
    }
}

class Solution {
    public int subtractProductAndSum(int n) {
        int[] values = productAndSum(n);
        return values[0] - values[1];
    }

    private int[] productAndSum(int n) {
        if (n < 10) {
            return new int[]{n, n};
        }
        int[] values = productAndSum(n / 10);
        int digit = n % 10;
        values[0] *= digit;
        values[1] += digit;
        return values;
    }
}

class Solution {
    public int subtractProductAndSum(int n) {
        int divisor = 1;
        while (divisor <= n / 10) {
            divisor *= 10;
        }

        int product = 1;
        int sum = 0;
        while (divisor > 0) {
            int digit = n / divisor;
            product *= digit;
            sum += digit;
            n %= divisor;
            divisor /= 10;
        }
        return product - sum;
    }
}
